<?php defined('BASEPATH') or exit('No direct script access allowed');$operationLabels=['contracts'=>'Contratos','tickets'=>'Chamados','projects'=>'Projetos'];$operationStates=['draft'=>'Rascunho','active'=>'Ativo','cancelled'=>'Cancelado','open'=>'Aberto','resolved'=>'Resolvido','closed'=>'Encerrado','completed'=>'Concluído'];$operationFileForms=function(string $kind,array $record)use($url,$hidden,$esc){foreach($record['files']??[] as $file){echo form_open($url);$hidden('operation_file'); ?><input type="hidden" name="operation_kind" value="<?= $esc($kind); ?>"><input type="hidden" name="resource_id" value="<?= (int)$record['id']; ?>"><input type="hidden" name="file_key" value="<?= $esc($file['file_key']); ?>"><button type="submit">Baixar anexo: <?= $esc($file['filename']); ?></button><?= form_close(); ?><?php if($kind==='tickets'&&($file['own_upload']??false)){ ?><p>Seu envio: visível a você e à equipe autorizada. A equipe pode publicar explicitamente para outros contatos autorizados deste cadastro.</p><?php if(($record['status']??null)==='open'&&isset($record['revision'])){ ?><?= form_open($url);$hidden('support_file_hide'); ?><input type="hidden" name="resource_id" value="<?= (int)$record['id']; ?>"><input type="hidden" name="revision" value="<?= (int)$record['revision']; ?>"><input type="hidden" name="request_key" value="<?= $esc(bin2hex(random_bytes(32))); ?>"><input type="hidden" name="file_key" value="<?= $esc($file['file_key']); ?>"><button type="submit">Ocultar seu anexo e preservar histórico</button><?= form_close(); ?><?php }} }}; ?>
<?php if($operation_detail??null){ ?><section id="portal-operation-detail"><h2><?= $esc($operationLabels[$operation_kind]); ?> — <?= $esc($operation_detail['name']); ?></h2><p><?= $esc($operationStates[$operation_detail['status']]??'Consultar empresa'); ?></p><?php if(isset($operation_detail['start_date'])){ ?><p>Vigência: <?= $esc($operation_detail['start_date'].' até '.$operation_detail['due_date']); ?></p><?php } ?><div style="white-space:pre-wrap"><?= $esc($operation_detail['body']??$operation_detail['description']??''); ?></div>
<?php if($operation_kind==='tickets'){ ?><h3>Histórico de mensagens disponíveis</h3><?php foreach($operation_detail['replies'] as $reply){ ?><article><p style="white-space:pre-wrap"><?= $esc($reply['body']); ?></p><small><?= $esc($reply['contact_author']??null ? 'Contato: '.$reply['contact_author'] : 'Equipe da empresa'); ?> · <?= $esc($reply['created_at']); ?></small></article><?php } ?><?php } ?>
<?php if($operation_kind==='tickets'&&$operation_detail['status']==='open'){ ?><?= form_open_multipart($url,['id'=>'portal-support-upload']);$hidden('support_file_upload'); ?><input type="hidden" name="resource_id" value="<?= (int)$operation_detail['id']; ?>"><input type="hidden" name="revision" value="<?= (int)$operation_detail['revision']; ?>"><input type="hidden" name="request_key" value="<?= $esc(bin2hex(random_bytes(32))); ?>"><label for="portal-support-file">Anexo para você e a equipe desta empresa</label><input id="portal-support-file" type="file" name="operation_file" accept=".pdf,.png,.jpg,.jpeg" required><p>PDF até2 MiB ou PNG/JPEG até512 KiB, normalizados. Até20 arquivos/20 MiB no chamado, incluindo ocultos. Outros contatos deste cadastro só terão acesso se a equipe publicar este arquivo explicitamente. Ocultar retira acesso de todos os contatos e preserva o registro interno.</p><button type="submit">Anexar para você e a equipe</button><?= form_close(); ?><?php } ?>
<?php if($operation_kind==='tickets'&&$operation_detail['status']==='open'){ ?><?= form_open($url,['id'=>'portal-support-reply']);$hidden('support_reply'); ?><input type="hidden" name="resource_id" value="<?= (int)$operation_detail['id']; ?>"><input type="hidden" name="revision" value="<?= (int)$operation_detail['revision']; ?>"><input type="hidden" name="request_key" value="<?= $esc(bin2hex(random_bytes(32))); ?>"><label for="portal-support-message">Responder ao chamado</label><textarea id="portal-support-message" name="reply" maxlength="12000" rows="6" required></textarea><p>Sua mensagem será registrada para seu cadastro e para a equipe desta empresa.</p><button type="submit">Enviar resposta</button><?= form_close(); ?><?php }elseif($operation_kind==='tickets'){ ?><p>Chamado encerrado para novas respostas. Abra um novo chamado se precisar de atendimento.</p><?php } ?>
<?php if($operation_kind==='contracts'){ ?><section id="portal-contract-discussion"><h3>Conversa sobre este contrato</h3><p>Comentários são registros operacionais. Não representam assinatura, aceite jurídico ou alteração do texto do contrato. Sua mensagem ficará disponível à equipe e aos contatos autorizados deste cadastro no contrato publicado.</p><?php foreach($operation_detail['discussion']??[] as $comment){ ?><article><p style="white-space:pre-wrap"><?= $esc($comment['body']); ?></p><small><?= $esc(($comment['author_type']==='contact'?'Contato: ':'Equipe: ').$comment['author_name']); ?> · <?= $esc($comment['created_at']); ?></small></article><?php } ?><?= form_open($url,['id'=>'portal-contract-comment']);$hidden('contract_discussion'); ?><input type="hidden" name="resource_id" value="<?= (int)$operation_detail['id']; ?>"><input type="hidden" name="revision" value="<?= (int)$operation_detail['revision']; ?>"><input type="hidden" name="request_key" value="<?= $esc(bin2hex(random_bytes(32))); ?>"><label for="portal-contract-comment-body">Seu comentário em texto</label><textarea id="portal-contract-comment-body" name="discussion_body" maxlength="8000" rows="6" required></textarea><button type="submit">Registrar comentário</button><?= form_close(); ?></section><?php } ?>
<?php if($operation_kind==='contracts'){ ?><?= form_open($url);$hidden('operation_contract_pdf'); ?><input type="hidden" name="resource_id" value="<?= (int)$operation_detail['id']; ?>"><button type="submit">Baixar PDF do contrato</button><?= form_close(); ?><p>Documento de registro. A disponibilização no portal não representa assinatura ou aceite eletrônico.</p><?php }$operationFileForms($operation_kind,$operation_detail); ?><a href="<?= $esc($url); ?>">Voltar às listas</a></section><?php } ?>
<?php foreach($operations??[] as $kind=>$page){if(!is_array($page))continue; ?><section id="portal-<?= $esc($kind); ?>"><h2><?= $esc($operationLabels[$kind]); ?> desta empresa</h2><p>Somente registros publicados para seu cadastro, com permissão específica. Documentos, mensagens e anexos internos não publicados permanecem privados.</p><?php foreach($page['items'] as $record){ ?><article><h3><a href="<?= $esc($url.'?operation_kind='.$kind.'&resource_id='.(int)$record['id']); ?>"><?= $esc($record['name']); ?></a></h3><p><?= $esc($operationStates[$record['status']]??'Consultar empresa'); ?></p><?php $operationFileForms($kind,$record); ?></article><?php }if(!$page['items']){ ?><p>Nenhum registro publicado disponível.</p><?php }if($page['next']!==null){ ?><a href="<?= $esc($url.'?op_after_'.$kind.'='.(int)$page['next']); ?>">Próxima página de <?= $esc(mb_strtolower($operationLabels[$kind])); ?></a><?php } ?></section><?php } ?>

<?php if(is_array($operations['tickets']??null)){ ?><section id="portal-support-open"><h2>Abrir chamado nesta empresa</h2><p>O chamado pertence ao seu cadastro e será recebido pela equipe, inicialmente sem responsável atribuído. Até10 novos chamados por contato por hora e100 chamados abertos por cadastro. Nenhum e-mail é enviado automaticamente.</p><?= form_open($url);$hidden('support_open'); ?><input type="hidden" name="request_key" value="<?= $esc(bin2hex(random_bytes(32))); ?>"><label for="portal-support-subject">Assunto</label><input id="portal-support-subject" name="support[subject]" maxlength="191" required><label for="portal-support-body">Mensagem inicial</label><textarea id="portal-support-body" name="support[body]" maxlength="12000" rows="6" required></textarea><label for="portal-support-priority">Prioridade</label><select id="portal-support-priority" name="support[priority]"><option value="low">Baixa</option><option value="normal" selected>Normal</option><option value="high">Alta</option></select><button type="submit">Abrir chamado</button><?= form_close(); ?></section><?php } ?>
